icate view</button><button type="button" id="settings-rename-view" disabled>Rename view</button><button type="button" id="settings-delete-view" disabled>Delete view</button><input type="file" id="settings-import-views-file" accept="application/json,.json" hidden><button type="button" id="settings-import-views">Import file</button><button type="button" id="settings-export-views">Copy JSON</button><button type="button" id="settings-download-views">Download JSON</button><button type="button" id="settings-view-diagnostics">Copy diagnostics</button><button type="button" id="settings-repair-views">Repair views</button><button type="button" id="settings-reset-personal-workspace">Reset personal workspace</button><button type="button" id="settings-clear-views" disabled>Clear all views</button><button type="button" id="settings-copy-view">Copy view link</button><button type="button" id="settings-clear-target">Clear target</button><button type="button" id="settings-print">Print</button></div></section><section class="settings-action-group" aria-labelledby="settings-action-display-title"><strong class="settings-action-group-title" id="settings-action-display-title">Section display</strong><div class="settings-action-group-body"><button type="button" id="settings-expand-all">Expand all</button><button type="button" id="settings-collapse-all">Collapse all</button></div></section></div></details>
