      <?php if(count($sections)>1): ?><nav class="settings-section-nav" aria-label="<?= $e(($categoryLabels[$category]??ucfirst($category)).' sections') ?>"><?php foreach($sections as $navSection): ?><a href="#section-<?= $e($navSection->id) ?>"><?= $e($navSection->label) ?></a><?php endforeach; ?></nav><?php endif; ?>
      <?php foreach($sections as $section): ?>
        <?php $sectionView=$sectionPresentation[$section->id]; ?>
        <article class="settings-section" id="section-<?= $e($section->id) ?>" data-settings-card data-section-id="<?= $e($section->id) ?>" data-settings-module="<?= $e($section->module) ?>" data-search="<?= $e($sectionView['search']) ?>">
          <header class="settings-section-head"><h2><?= $e($section->label) ?></h2><?php if($section->description!==''): ?><p class="settings-muted"><?= $e($section->description) ?></p><?php endif; ?><div class="settings-meta"><span class="settings-badge"><?= $e($section->module) ?></span><span class="settings-badge"><?= $e((string)count($section->groups)) ?> group<?= count($section->groups)===1?'':'s' ?></span><span class="settings-badge"><?= $e((string)count($section->settings)) ?> field<?= count($section->settings)===1?'':'s' ?></span></div></header>
          <?php if($sectionView['editable']): ?><form method="post" action="<?= $e($saveUrl) ?>" data-settings-form data-section-label="<?= $e($section->label) ?>"><input type="hidden" name="_csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="section" value="<?= $e($section->id) ?>"><input type="hidden" name="scope" value="<?= $e($scopeType) ?>"><input type="hidden" name="scope_key" value="<?= $e($scopeKey) ?>"><?php endif; ?>
          <?php foreach($section->groups as $group): ?>
            <details class="settings-group" id="group-<?= $e($section->id.'-'.$group->id) ?>" data-settings-group data-group-key="<?= $e($section->id.'.'.$group->id) ?>" <?= $group->openByDefault ? 'data-open-default open' : '' ?>>
              <summary><span><?= $e($group->label) ?><?php if($group->description!==''): ?><small class="settings-muted"> · <?= $e($group->description) ?></small><?php endif; ?></span><span class="settings-badge"><?= $e((string)count($group->settings)) ?></span></summary>
              <div class="settings-group-body">
              <?php foreach($group->settings as $setting): $effective=$effectiveValues[$setting->path];$fieldView=$fieldPresentation[$setting->path]; ?>
                <div class="settings-field" id="<?= $e($fieldView['id']) ?>" data-setting-field="<?= $e($setting->path) ?>" data-setting-source="<?= $e($effective->source) ?>" data-setting-readonly="<?= $effective->readOnly ? 'true' : 'false' ?>" data-setting-editable="<?= $fieldView['editable'] ? 'true' : 'false' ?>"><div class="settings-field-row"><div class="settings-field-heading"><strong><?= $e($setting->label) ?></strong><a class="settings-icon-button" href="#<?= $e($fieldView['id']) ?>" aria-label="Link to <?= $e($setting->label) ?>">Link</a><?php if($showPaths): ?><button class="settings-icon-button" type="button" data-copy-setting-path="<?= $e($setting->path) ?>">Copy path</button><?php endif; ?></div><span class="settings-badge"><?= $e($setting->type) ?></span></div><?php if($showPaths): ?><code><?= $e($setting->path) ?></code><?php endif; ?><?php if($setting->description!==''): ?><p class="settings-muted"><?= $e($setting->description) ?></p><?php endif; ?><div class="settings-meta"><span class="settings-badge">Source: <?= $e(ucfirst($effective->source)) ?></span><?php if($effective->readOnly): ?><span class="settings-badge">Read-only</span><?php endif; ?><?php if($effective->secret): ?><span class="settings-badge">Secret</span><?php endif; ?></div><strong>Effective value</strong><br><code><?= $e($fieldView['displayValue']) ?></code><?php if($effective->explanation!==null): ?><p class="settings-muted" data-field-explanation><?= $e($effective->explanation) ?></p><?php endif; ?>
                <?php if($fieldView['editable']): $inputName=$fieldView['inputName']; ?>
                  <?php if($setting->type==='boolean'): ?><span class="settings-edit-control"><input type="hidden" name="<?= $e($inputName) ?>" value="0"><label><input type="checkbox" name="<?= $e($inputName) ?>" value="1" <?= $fieldView['checked']?'checked':'' ?>> Enabled</label>
                  <?php elseif($setting->type==='textarea'): ?><span class="settings-edit-control"><textarea class="settings-input" name="<?= $e($inputName) ?>" rows="4"><?= $e($fieldView['inputValue']) ?></textarea></span><span class="settings-print-value"><?= $e($fieldView['displayValue']) ?></span>
                  <?php elseif($setting->type==='select'): ?><span class="settings-edit-control"><select class="settings-input" name="<?= $e($inputName) ?>"><?php foreach($setting->options as $option): ?><option value="<?= $e($option) ?>" <?= (string)$effective->value===$option?'selected':'' ?>><?= $e($option) ?></option><?php endforeach; ?></select></span><span class="settings-print-value"><?= $e($fieldView['displayValue']) ?></span>
                  <?php elseif($setting->type==='multiselect'): $selectedValues=$fieldView['selectedValues']; ?><span class="settings-edit-control"><select class="settings-input" name="<?= $e($inputName) ?>[]" multiple><?php foreach($setting->options as $option): ?><option value="<?= $e($option) ?>" <?= in_array($option,$selectedValues,true)?'selected':'' ?>><?= $e($option) ?></option><?php endforeach; ?></select></span><span class="settings-print-value"><?= $e($fieldView['displayValue']) ?></span>
                  <?php else: $inputType=$fieldView['inputType']; ?><span class="settings-edit-control"><input class="settings-input" type="<?= $e($inputType) ?>" name="<?= $e($inputName) ?>" value="<?= $e($fieldView['inputValue']) ?>" <?= $fieldView['step']!==''?'step="'.$e($fieldView['step']).'"':'' ?>></span><span class="settings-print-value"><?= $e($fieldView['displayValue']) ?></span><?php endif; ?>
                  <?php if($effective->source==='database'): ?><button class="settings-clear" type="submit" name="path" value="<?= $e($setting->path) ?>" formaction="<?= $e($clearUrl) ?>" formmethod="post">Use inherited value</button><?php endif; ?>
                <?php endif; ?></div>
              <?php endforeach; ?>
              </div>
            </details>
          <?php endforeach; ?>
          <?php if($sectionView['editable']): ?><footer class="settings-actions"><span class="settings-muted" data-form-status aria-live="polite">No unsaved changes</span><button class="settings-clear" type="button" data-reset-section disabled>Reset section</button><button class="settings-save" type="submit" data-save-section disabled>Save <?= $e($section->label) ?></button></footer></form><?php endif; ?>
        </article>
      <?php endforeach; ?></section>
